<template>
  <v-container fluid class="tenant-page">
    <div class="page-header"><div><h1>Tenantlar</h1><p>Sistemde tanımlı tenant hesaplarını görüntüleyin ve yönetin.</p></div></div>

    <v-card class="filter-card" elevation="0">
      <v-text-field v-model="search" placeholder="Tenant ara..." prepend-inner-icon="mdi-magnify" variant="outlined" density="comfortable" hide-details clearable />
      <v-select v-model="statusFilter" label="Durum" :items="statusOptions" variant="outlined" density="comfortable" hide-details />
      <v-select v-model="structureFilter" label="Kurumsal Yapı" :items="structureOptions" variant="outlined" density="comfortable" hide-details />
      <v-select v-model="dateFilter" label="Oluşturulma Tarihi" :items="dateOptions" variant="outlined" density="comfortable" hide-details prepend-inner-icon="mdi-calendar-outline" />
      <v-btn color="primary" class="new-tenant-button" rounded="lg" prepend-icon="mdi-plus" @click="goToCreate">Yeni Tenant</v-btn>
    </v-card>

    <v-card class="table-card" elevation="0">
      <div class="table-scroll"><table class="tenant-table">
        <thead><tr><th>Tenant Adı</th><th>Slug</th><th>Kurumsal Yapı</th><th>Durum</th><th>Oluşturulma Tarihi</th><th>İşlemler</th></tr></thead>
        <tbody>
          <tr v-for="tenant in paginatedTenants" :key="tenant.id" class="tenant-row" @click="openTenant(tenant)">
            <td><div class="tenant-cell"><div class="tenant-avatar" :class="`avatar-${tenant.id}`">{{ getInitials(tenant.name) }}</div><div><div class="tenant-name">{{ tenant.name }}</div><div class="tenant-id">#{{ tenant.id }}</div></div></div></td>
            <td class="muted">{{ tenant.slug }}</td>
            <td><span class="structure-badge" :class="`structure-${tenant.onboarding_type}`"><v-icon :icon="getStructureIcon(tenant.onboarding_type)" size="14" />{{ getStructureLabel(tenant.onboarding_type) }}</span></td>
            <td><span class="status-badge" :class="tenant.status === 'active' ? 'active' : 'passive'"><span class="status-dot" />{{ tenant.status === 'active' ? 'Aktif' : 'Pasif' }}</span></td>
            <td class="muted">{{ formatDate(tenant.created_at) }}</td>
            <td class="actions-cell"><v-menu><template #activator="{ props }"><v-btn v-bind="props" icon="mdi-dots-vertical" variant="text" size="small" @click.stop /></template><v-list density="compact"><v-list-item prepend-icon="mdi-eye-outline" title="Görüntüle" @click="openTenant(tenant)" /><v-list-item prepend-icon="mdi-pencil-outline" title="Düzenle" @click="editTenant(tenant)" /><v-divider /><v-list-item :prepend-icon="tenant.status === 'active' ? 'mdi-close-circle-outline' : 'mdi-check-circle-outline'" :title="tenant.status === 'active' ? 'Pasife Al' : 'Aktifleştir'" @click="toggleStatus(tenant)" /></v-list></v-menu></td>
          </tr>
          <tr v-if="paginatedTenants.length === 0"><td colspan="6"><div class="empty-state"><v-icon icon="mdi-domain-off" size="42" /><div class="empty-title">Tenant bulunamadı</div><div class="empty-text">Arama veya filtre kriterlerinizi değiştirmeyi deneyin.</div></div></td></tr>
        </tbody>
      </table></div>

      <div class="table-footer"><span class="record-count">Toplam 24 kayıt</span><div class="pagination-area"><v-pagination v-model="page" :length="pageCount" :total-visible="5" density="comfortable" class="pagination" /><v-select v-model="itemsPerPage" :items="[10,25,50]" variant="outlined" density="compact" hide-details class="page-size" suffix="/ sayfa" /></div></div>
    </v-card>
  </v-container>
</template>

<script setup lang="ts">
interface Tenant { id:number; name:string; slug:string; status:'active'|'passive'; onboarding_type:'holding'|'group'|'company'|'brand'; created_at:string }
const router=useRouter(); const search=ref(''); const statusFilter=ref<string|null>(null); const structureFilter=ref<string|null>(null); const dateFilter=ref<string|null>(null); const page=ref(1); const itemsPerPage=ref(10)
const statusOptions=[{title:'Tümü',value:null},{title:'Aktif',value:'active'},{title:'Pasif',value:'passive'}]
const structureOptions=[{title:'Tümü',value:null},{title:'Holding',value:'holding'},{title:'Grup',value:'group'},{title:'Şirket',value:'company'},{title:'Marka',value:'brand'}]
const dateOptions=[{title:'Tümü',value:null},{title:'Son 7 gün',value:'7'},{title:'Son 30 gün',value:'30'}]
const tenants=ref<Tenant[]>([
{id:1,name:'Koç Holding',slug:'koc-holding',status:'active',onboarding_type:'holding',created_at:'2025-05-18T14:32:00'},
{id:2,name:'MADO',slug:'mado',status:'active',onboarding_type:'company',created_at:'2025-05-17T11:20:00'},
{id:3,name:'Arçelik A.Ş.',slug:'arcelik',status:'active',onboarding_type:'company',created_at:'2025-05-16T09:15:00'},
{id:4,name:'İpek Gıda',slug:'ipek-gida',status:'passive',onboarding_type:'group',created_at:'2025-05-15T16:45:00'},
{id:5,name:'Tepe Savunma',slug:'tepe-savunma',status:'active',onboarding_type:'company',created_at:'2025-05-14T10:05:00'},
{id:6,name:'Beko',slug:'beko',status:'active',onboarding_type:'brand',created_at:'2025-05-13T13:30:00'},
{id:7,name:'Setur',slug:'setur',status:'passive',onboarding_type:'company',created_at:'2025-05-12T08:50:00'}])
const filteredTenants=computed(()=>{const q=search.value.trim().toLocaleLowerCase('tr-TR');return tenants.value.filter(t=>(!q||t.name.toLocaleLowerCase('tr-TR').includes(q)||t.slug.toLocaleLowerCase('tr-TR').includes(q))&&(!statusFilter.value||t.status===statusFilter.value)&&(!structureFilter.value||t.onboarding_type===structureFilter.value))})
const pageCount=computed(()=>Math.max(1,Math.ceil(filteredTenants.value.length/itemsPerPage.value))); const paginatedTenants=computed(()=>filteredTenants.value.slice((page.value-1)*itemsPerPage.value,page.value*itemsPerPage.value)); watch([search,statusFilter,structureFilter,dateFilter,itemsPerPage],()=>page.value=1)
function getInitials(n:string){return n.split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toLocaleUpperCase('tr-TR')}; function getStructureLabel(t:Tenant['onboarding_type']){return ({holding:'Holding',group:'Grup',company:'Şirket',brand:'Marka'} as const)[t]}; function getStructureIcon(t:Tenant['onboarding_type']){return ({holding:'mdi-bank-outline',group:'mdi-account-group-outline',company:'mdi-domain',brand:'mdi-tag-outline'} as const)[t]}; function formatDate(v:string){return new Intl.DateTimeFormat('tr-TR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v))}; function goToCreate(){router.push('/tenants/new')}; function openTenant(t:Tenant){router.push(`/tenants/${t.id}`)}; function editTenant(t:Tenant){router.push(`/tenants/${t.id}/edit`)}; function toggleStatus(t:Tenant){t.status=t.status==='active'?'passive':'active'}
</script>

