background:#fff0f3;color:#ef3b56}.avatar-7{background:#e7f8fc;color:#0a9fc4}.tenant-name{font-size:12px;font-weight:600;line-height:1.15}.tenant-id{margin-top:3px;color:#64748b;font-size:10px}.muted{color:#64748b!important}.structure-badge,.status-badge{display:inline-flex;align-items:center;gap:5px;border-radius:7px;padding:5px 9px;font-size:10px;font-weight:500;white-space:nowrap}.structure-holding{background:#eee9ff;color:#6546e8}.structure-group{background:#fff4df;color:#ef8c00}.structure-company{background:#e8f8f0;color:#079455}.structure-brand{background:#eaf2ff;color:#2563eb}.status-badge.active{background:#e8f8f1;color:#0aa56b}.status-badge.passive{background:#f0f2f5;color:#64748b}.status-dot{width:5px;height:5px;border-radius:50%;background:currentColor}.actions-cell{text-align:center}.actions-cell :deep(.v-btn){color:#334155}.table-footer{position:relative;min-height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 16px}.record-count{color:#64748b;font-size:11px}.pagination-area{display:flex;align-items:center;gap:12px}.pagination{position:absolute;left:50%;transform:translateX(-50%)}.pagination :deep(.v-pagination__list){gap:4px}.pagination :deep(.v-btn){min-width:30px;width:30px;height:30px;font-size:11px}.page-size{width:86px;margin-left:auto}.page-size :deep(.v-field){min-height:34px}.page-size :deep(.v-field__input){min-height:34px;padding:0 8px;font-size:10px}.page-size :deep(.v-field__suffix){font-size:10px;color:#64748b;padding-inline-start:0}.empty-state{min-height:220px;display:flex;align-items:center;justify-content:center;flex-direction:column;color:#94a3b8}.empty-title{margin-top:10px;font-size:13px;font-weight:600}.empty-text{margin-top:4px;font-size:11px}@media(max-width:1050px){.filter-card{grid-template-columns:1.5fr 1fr 1fr}.new-tenant-button{width:100%}}@media(max-width:700px){.tenant-page{padding:16px!important}.filter-card{grid-template-columns:1fr}.table-footer{align-items:center;flex-direction:row;gap:8px;padding:0 12px}.pagination{position:static;transform:none}.pagination-area{margin-left:auto;gap:6px}.page-size{width:76px}}
</style>